// Build-time only. Paseo 0.8 evaluates client bundles without Metro/Babel;
// Hermes cannot load the class expression in markdown-it's UMD entity decoder.
// Lower the pinned, self-contained parser without changing its behavior or version.
import { createRequire } from "node:module";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import ts from "typescript";

const require = createRequire(import.meta.url);
const source = await readFile(require.resolve("markdown-it/dist/markdown-it.js"), "utf8");
const result = ts.transpileModule(source, {
  fileName: "markdown-it.js",
  compilerOptions: {
    allowJs: true, target: ts.ScriptTarget.ES5, module: ts.ModuleKind.CommonJS,
    downlevelIteration: true, removeComments: false,
  },
  reportDiagnostics: true,
});
const errors = result.diagnostics?.filter(diagnostic => diagnostic.category === ts.DiagnosticCategory.Error) ?? [];
if (errors.length) throw new Error(errors.map(diagnostic => ts.flattenDiagnosticMessageText(diagnostic.messageText, "\n")).join("\n"));

const directory = new URL("../shared/generated/", import.meta.url);
await mkdir(directory, { recursive: true });
// Export as ESM: the host's eager CJS interop otherwise reads the constructor's
// restricted caller/arguments properties in Hermes. Keep UMD globals local.
await writeFile(new URL("markdown.js", directory),
  "// GENERATED by npm run prepare:markdown; do not commit.\n" +
  "const parser = (() => {\nconst module = { exports: {} };\nconst exports = module.exports;\n" +
  result.outputText.replace(/^\/\/# sourceMappingURL=.*$/gm, "") +
  "\nreturn module.exports;\n})();\nexport default parser;\n");
await writeFile(new URL("markdown.d.ts", directory),
  'import MarkdownIt from "markdown-it";\nexport default MarkdownIt;\n');
console.log("Prepared Hermes-compatible Markdown parser");
